// Extract and normalize input
const body = $json.body || $json;
const query = body.query || body.text || '';
const action = body.action || 'chat';
let language = body.language || 'en';
const policies = body.policies || [];
const hasPolicies = Array.isArray(policies) && policies.length > 0;

// Auto-detect language from query text
const detectLanguage = (text) => {
  // Hindi (Devanagari)
  if (/[\u0900-\u097F]/.test(text)) return 'hi';
  // Tamil
  if (/[\u0B80-\u0BFF]/.test(text)) return 'ta';
  // Telugu
  if (/[\u0C00-\u0C7F]/.test(text)) return 'te';
  // Kannada
  if (/[\u0C80-\u0CFF]/.test(text)) return 'kn';
  // Malayalam
  if (/[\u0D00-\u0D7F]/.test(text)) return 'ml';

  // Transliterated Hindi detection
  const hindiWords = ['mera', 'meri', 'aapka', 'kya', 'hai', 'hoon', 'hain', 'kaise', 'kaisa', 'aap', 'main', 'bima', 'bimari', 'swasthya', 'namaste', 'dhanyawad', 'paisa', 'rupay', 'kitna', 'kab', 'kahan', 'kyun', 'kaun', 'premium', 'claim', 'policy'];
  const words = text.toLowerCase().split(/\s+/);
  const hindiCount = words.filter(w => hindiWords.includes(w)).length;
  if (hindiCount >= 2 || (hindiCount >= 1 && words.length <= 5)) return 'hi';

  // Transliterated Tamil detection
  const tamilWords = ['vanakkam', 'enna', 'epdi', 'naan', 'neenga', 'enaku', 'unaku', 'inge', 'ange', 'seekiram', 'nandri', 'panam', 'kaapitu'];
  const tamilCount = words.filter(w => tamilWords.includes(w)).length;
  if (tamilCount >= 2 || (tamilCount >= 1 && words.length <= 5)) return 'ta';

  return 'en';
};

// Detect actual language from query
const detectedLang = detectLanguage(query);
language = detectedLang;

// Simple greeting detection
const greetingPatterns = [
  /^(hi|hello|hey|good\s*(morning|evening|afternoon|night))$/i,
  /^(vanakkam|வணக்கம்)$/i,
  /^(namaste|नमस्ते|namaskar|नमस्कार)$/i,
  /^(namaskaram|నమస్కారం|നമസ്കാരം|ನಮಸ್ಕಾರ)$/i
];

const isGreeting = greetingPatterns.some(p => p.test(query.trim()));
const isCompare = action === 'compare' || (hasPolicies && query.toLowerCase().includes('compare'));

let route = 'chat';
if (isGreeting) route = 'greeting';
else if (isCompare && hasPolicies) route = 'compare';

return {
  json: {
    query: query,
    language: language,
    detected_language: detectedLang,
    policies: policies,
    route: route
  }
};

