// Process compare response
let result = { recommended_index: 0, explanation: 'Unable to compare', scores: [] };
let success = true;

try {
  if ($json.choices?.[0]?.message?.content) {
    result = JSON.parse($json.choices[0].message.content);
  } else if ($json.error) {
    success = false;
    result.explanation = 'Service temporarily unavailable';
  }
} catch (e) {
  success = false;
  result.explanation = 'Error processing comparison';
}

return {
  json: {
    recommendation: JSON.stringify(result),
    language: $('Route Detector').first().json.language,
    intent: 'compare',
    success: success
  }
};

// Process chat response
const lang = $('Route Detector').first().json.language || 'en';
const detectedLang = $('Route Detector').first().json.detected_language || lang;
let response = '';
let success = true;

const fallback = {
  'en': "I'm having trouble right now. Please try again.",
  'hi': "मुझे अभी कुछ समस्या हो रही है। कृपया पुनः प्रयास करें।",
  'ta': "தற்போது சிக்கல் உள்ளது. மீண்டும் முயற்சிக்கவும்.",
  'te': "ప్రస్తుతం సమస్య ఉంది. దయచేసి మళ్ళీ ప్రయత్నించండి.",
  'kn': "ಸದ್ಯ ಸಮಸ್ಯೆ ಇದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  'ml': "ഇപ്പോൾ പ്രശ്നമുണ്ട്. ദയവായി വീണ്ടും ശ്രമിക്കുക."
};

try {
  if ($json.choices?.[0]?.message?.content) {
    response = $json.choices[0].message.content;
  } else {
    success = false;
    response = fallback[lang] || fallback['en'];
  }
} catch (e) {
  success = false;
  response = fallback[lang] || fallback['en'];
}

return {
  json: {
    response: response,
    language: lang,
    detected_language: detectedLang,
    intent: 'chat',
    success: success
  }
};
